import { useState, useEffect } from 'react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from './ui/dialog'
import { Calendar, Clock, MapPin, Users, AlertTriangle, Repeat, Settings, Plus } from 'lucide-react'
import { motion } from 'framer-motion'
import TeamSelectorForEvent from './TeamSelectorForEvent'

interface Venue {
  id: string
  name: string
  address?: string
}

interface Event {
  id?: string
  title: string
  description: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id: string
  team_ids: number[]
  is_recurring: boolean
  recurrence_rule?: string
  status?: 'scheduled' | 'completed' | 'cancelled'
}

interface EventFormData {
  title: string
  description: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id: string
  team_ids: number[]
  is_recurring: boolean
  recurrence_rule: string
}

interface EventFormProps {
  mode: 'create' | 'edit'
  event?: Event
  isModal?: boolean
  onSubmit: (eventData: EventFormData) => Promise<void>
  onCancel: () => void
  loading?: boolean
}

const EventForm = ({ mode, event, isModal = false, onSubmit, onCancel, loading = false }: EventFormProps) => {
  const [venues, setVenues] = useState<Venue[]>([])
  const [formData, setFormData] = useState<EventFormData>({
    title: '',
    description: '',
    event_type: 'practice',
    start_time: '',
    end_time: '',
    venue_id: '',
    team_ids: [],
    is_recurring: false,
    recurrence_rule: ''
  })
  const [formErrors, setFormErrors] = useState<Partial<EventFormData>>({})

  // Pre-populate form data when editing
  useEffect(() => {
    if (mode === 'edit' && event) {
      setFormData({
        title: event.title,
        description: event.description,
        event_type: event.event_type,
        start_time: event.start_time,
        end_time: event.end_time,
        venue_id: event.venue_id,
        team_ids: event.team_ids,
        is_recurring: event.is_recurring,
        recurrence_rule: event.recurrence_rule || ''
      })
    }
  }, [mode, event])

  // Fetch venues
  useEffect(() => {
    fetchVenues()
  }, [])

  const fetchVenues = async () => {
    try {
      const response = await fetch('/api/venues')
      if (!response.ok) {
        throw new Error('Failed to fetch venues')
      }
      const venuesData = await response.json()
      setVenues(venuesData)
    } catch (err) {
      console.error('Error fetching venues:', err)
      // Fallback to empty array
      setVenues([])
    }
  }

  const validateForm = (data: EventFormData): boolean => {
    const errors: Partial<EventFormData> = {}

    // Required field validation
    if (!data.title.trim()) {
      errors.title = 'Event title is required'
    }
    if (!data.event_type) {
      errors.event_type = 'Event type is required'
    }
    if (!data.start_time) {
      errors.start_time = 'Start time is required'
    }
    if (!data.end_time) {
      errors.end_time = 'End time is required'
    }
    if (!data.venue_id) {
      errors.venue_id = 'Venue selection is required'
    }
    if (data.team_ids.length === 0) {
      errors.team_ids = 'At least one team must be selected'
    }

    // Time logic validation
    if (data.start_time && data.end_time) {
      const startDate = new Date(data.start_time)
      const endDate = new Date(data.end_time)

      if (endDate <= startDate) {
        errors.end_time = 'End time must be after start time'
      }

      if (startDate < new Date()) {
        errors.start_time = 'Start time cannot be in the past'
      }
    }

    // Recurrence rule validation
    if (data.is_recurring && !data.recurrence_rule.trim()) {
      errors.recurrence_rule = 'Recurrence rule is required for recurring events'
    }

    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  const handleSubmit = async () => {
    if (!validateForm(formData)) return

    try {
      await onSubmit(formData)
    } catch (err) {
      console.error('Form submission error:', err)
    }
  }

  const handleTeamsChange = (teamIds: number[]) => {
    setFormData(prev => ({
      ...prev,
      team_ids: teamIds
    }))
  }

  const getEventTypeIcon = (type: string) => {
    switch (type) {
      case 'game':
        return Users
      case 'practice':
        return Settings
      case 'tournament':
        return Plus
      default:
        return Calendar
    }
  }

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'game':
        return 'from-blue-600 to-blue-700'
      case 'practice':
        return 'from-green-600 to-green-700'
      case 'tournament':
        return 'from-purple-600 to-purple-700'
      default:
        return 'from-gray-600 to-gray-700'
    }
  }

  const formContent = (
    <div className="space-y-6">
      {/* Event Basic Information */}
      <div className="space-y-4">
        <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
          <Calendar className="w-5 h-5 text-orange-600" />
          Event Information
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">Event Title *</label>
            <Input
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="Enter event title"
              className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground placeholder:text-muted-foreground transition-all duration-200 ${
                formErrors.title
                  ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                  : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
              }`}
            />
            {formErrors.title && (
              <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
                <AlertTriangle className="w-4 h-4" />
                {formErrors.title}
              </p>
            )}
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">Event Type *</label>
            <select
              value={formData.event_type}
              onChange={(e) => setFormData({ ...formData, event_type: e.target.value as EventFormData['event_type'] })}
              className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground transition-all duration-200 ${
                formErrors.event_type
                  ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                  : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
              }`}
            >
              <option value="practice">Practice</option>
              <option value="game">Game</option>
              <option value="tournament">Tournament</option>
            </select>
            {formErrors.event_type && (
              <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
                <AlertTriangle className="w-4 h-4" />
                {formErrors.event_type}
              </p>
            )}
          </div>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-medium text-foreground">Description</label>
          <textarea
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            rows={3}
            placeholder="Enter event description..."
            className="w-full px-4 py-3 rounded-lg border-2 border-border bg-background text-foreground placeholder:text-muted-foreground focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20 transition-all duration-200 resize-none"
          />
        </div>
      </div>

      {/* Date and Time */}
      <div className="space-y-4 pt-6 border-t border-border">
        <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
          <Clock className="w-5 h-5 text-orange-600" />
          Schedule
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">Start Time *</label>
            <Input
              type="datetime-local"
              value={formData.start_time}
              onChange={(e) => setFormData({ ...formData, start_time: e.target.value })}
              className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground transition-all duration-200 ${
                formErrors.start_time
                  ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                  : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
              }`}
            />
            {formErrors.start_time && (
              <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
                <AlertTriangle className="w-4 h-4" />
                {formErrors.start_time}
              </p>
            )}
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">End Time *</label>
            <Input
              type="datetime-local"
              value={formData.end_time}
              onChange={(e) => setFormData({ ...formData, end_time: e.target.value })}
              className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground transition-all duration-200 ${
                formErrors.end_time
                  ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                  : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
              }`}
            />
            {formErrors.end_time && (
              <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
                <AlertTriangle className="w-4 h-4" />
                {formErrors.end_time}
              </p>
            )}
          </div>
        </div>
      </div>

      {/* Venue Selection */}
      <div className="space-y-4 pt-6 border-t border-border">
        <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
          <MapPin className="w-5 h-5 text-orange-600" />
          Venue
        </h3>
        <div className="space-y-2">
          <label className="block text-sm font-medium text-foreground">Select Venue *</label>
          <select
            value={formData.venue_id}
            onChange={(e) => setFormData({ ...formData, venue_id: e.target.value })}
            className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground transition-all duration-200 ${
              formErrors.venue_id
                ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
            }`}
          >
            <option value="">Select a venue...</option>
            {venues.map(venue => (
              <option key={venue.id} value={venue.id}>
                {venue.name} {venue.address && `- ${venue.address}`}
              </option>
            ))}
          </select>
          {formErrors.venue_id && (
            <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
              <AlertTriangle className="w-4 h-4" />
              {formErrors.venue_id}
            </p>
          )}
        </div>
      </div>

      {/* Team Selection */}
      <div className="space-y-4 pt-6 border-t border-border">
        <TeamSelectorForEvent
          selectedTeamIds={formData.team_ids}
          onTeamsChange={handleTeamsChange}
          disabled={loading}
        />
        {formErrors.team_ids && (
          <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
            <AlertTriangle className="w-4 h-4" />
            {formErrors.team_ids}
          </p>
        )}
      </div>

      {/* Recurring Event */}
      <div className="space-y-4 pt-6 border-t border-border">
        <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
          <Repeat className="w-5 h-5 text-orange-600" />
          Recurrence
        </h3>
        <div className="space-y-4">
          <label className="flex items-center space-x-2 cursor-pointer">
            <input
              type="checkbox"
              checked={formData.is_recurring}
              onChange={(e) => setFormData({ ...formData, is_recurring: e.target.checked, recurrence_rule: e.target.checked ? formData.recurrence_rule : '' })}
              className="rounded border-border focus:ring-orange-500"
            />
            <span className="text-sm font-medium text-foreground">This is a recurring event</span>
          </label>

          {formData.is_recurring && (
            <div className="space-y-2">
              <label className="block text-sm font-medium text-foreground">Recurrence Rule *</label>
              <select
                value={formData.recurrence_rule}
                onChange={(e) => setFormData({ ...formData, recurrence_rule: e.target.value })}
                className={`w-full px-4 py-3 rounded-lg border-2 bg-background text-foreground transition-all duration-200 ${
                  formErrors.recurrence_rule
                    ? 'border-red-500 focus:border-red-500 focus:ring-2 focus:ring-red-500/20'
                    : 'border-border focus:border-orange-500 focus:ring-2 focus:ring-orange-500/20'
                }`}
              >
                <option value="">Select recurrence pattern...</option>
                <option value="DAILY">Daily</option>
                <option value="WEEKLY">Weekly</option>
                <option value="BIWEEKLY">Every 2 weeks</option>
                <option value="MONTHLY">Monthly</option>
              </select>
              {formErrors.recurrence_rule && (
                <p className="text-sm text-red-500 mt-1 flex items-center gap-1">
                  <AlertTriangle className="w-4 h-4" />
                  {formErrors.recurrence_rule}
                </p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )

  if (isModal) {
    return (
      <Dialog open={true} onOpenChange={onCancel}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto animate-scale bg-white border-gray-200">
          <DialogHeader className="text-center pb-6">
            <div className="flex justify-center mb-4">
              <div className={`w-12 h-12 bg-gradient-to-r ${getEventTypeColor(formData.event_type)} rounded-xl flex items-center justify-center shadow-lg glow-border floating-element`}>
                {(() => {
                  const IconComponent = getEventTypeIcon(formData.event_type)
                  return <IconComponent className="w-6 h-6 text-white" />
                })()}
              </div>
            </div>
            <DialogTitle className="gradient-text text-3xl font-bold">
              {mode === 'create' ? 'Create New Event' : 'Edit Event'}
            </DialogTitle>
            <DialogDescription className="text-muted-foreground mt-2">
              {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
            </DialogDescription>
          </DialogHeader>

          {formContent}

          <DialogFooter className="mt-8 pt-6 border-t border-border gap-3">
            <Button
              variant="outline"
              onClick={onCancel}
              className="px-6 py-3 border-2 border-border hover:bg-secondary transition-all duration-200"
            >
              Cancel
            </Button>
            <motion.button
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              onClick={handleSubmit}
              disabled={loading}
              className={`bg-gradient-to-r ${getEventTypeColor(formData.event_type)} hover:opacity-90 text-white font-semibold px-8 py-3 rounded-lg transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-xl`}
            >
              <span>{loading ? (mode === 'create' ? 'Creating Event...' : 'Updating Event...') : (mode === 'create' ? 'Create Event' : 'Update Event')}</span>
            </motion.button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    )
  }

  // Standalone page mode
  return (
    <div className="space-y-6">
      <div className="flex items-center space-x-4 mb-6">
        <div className={`w-12 h-12 bg-gradient-to-r ${getEventTypeColor(formData.event_type)} rounded-xl flex items-center justify-center shadow-lg`}>
          {(() => {
            const IconComponent = getEventTypeIcon(formData.event_type)
            return <IconComponent className="w-6 h-6 text-white" />
          })()}
        </div>
        <div>
          <h1 className="text-3xl font-bold text-foreground">
            {mode === 'create' ? 'Create New Event' : 'Edit Event'}
          </h1>
          <p className="text-muted-foreground">
            {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
          </p>
        </div>
      </div>

      <div className="bg-background border border-border rounded-lg p-6">
        {formContent}

        <div className="flex items-center justify-end space-x-4 mt-8 pt-6 border-t border-border">
          <Button
            variant="outline"
            onClick={onCancel}
            className="px-6 py-3"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={loading}
            className={`bg-gradient-to-r ${getEventTypeColor(formData.event_type)} hover:opacity-90 text-white px-8 py-3`}
          >
            {loading ? (mode === 'create' ? 'Creating Event...' : 'Updating Event...') : (mode === 'create' ? 'Create Event' : 'Update Event')}
          </Button>
        </div>
      </div>
    </div>
  )
}

export default EventForm

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  Calendar,
  Clock,
  MapPin,
  Repeat,
  AlertTriangle,
  Search,
  Check,
  X,
  Settings,
  Users,
  Trophy
} from 'lucide-react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import { Card, CardContent, CardHeader, CardTitle } from './ui/card'
import { Alert, AlertDescription } from './ui/alert'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from './ui/dialog'
import { useApi } from '../hooks/useApi'

interface Venue {
  id: string
  name: string
  address?: string
  city?: string
  state?: string
  zip_code?: string
  capacity?: number
  description?: string
  is_active?: boolean
}

interface VenuesResponse {
  venues: Venue[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

interface Event {
  id: string
  title: string
  description?: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id?: string
  venues?: Venue
  created_by_user_id?: number
  is_recurring: boolean
  recurrence_rule?: string
  status: 'scheduled' | 'completed' | 'cancelled'
  created_at: string
  updated_at: string
}

interface EventFormData {
  name: string
  description: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id: string
  created_by_user_id?: number
  is_recurring: boolean
  recurrence_rule: string
}

interface EventFormComponentProps {
  mode: 'create' | 'edit'
  eventId?: string
  initialDate?: Date
  onSuccess?: (event: Event) => void
  onCancel?: () => void
  isModal?: boolean
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function EventFormComponent({
  mode = 'create',
  eventId,
  initialDate,
  onSuccess,
  onCancel,
  isModal = false
}: EventFormComponentProps) {
  const [formData, setFormData] = useState<EventFormData>({
    name: '',
    description: '',
    event_type: 'practice',
    start_time: '',
    end_time: '',
    venue_id: '',
    created_by_user_id: undefined,
    is_recurring: false,
    recurrence_rule: ''
  })

  const [formErrors, setFormErrors] = useState<Partial<Record<keyof EventFormData, string>>>({})
  const [venueSearch, setVenueSearch] = useState('')
  const [showVenueDropdown, setShowVenueDropdown] = useState(false)
  const [successMessage, setSuccessMessage] = useState('')

  // API hooks
  const { data: venuesData, loading: venuesLoading, execute: fetchVenues } = useApi<VenuesResponse>()
  const { data: eventData, loading: eventLoading, execute: fetchEvent } = useApi<Event>()
  const { loading: submitting, error: submitError, execute: submitEvent } = useApi<Event>()

  // Initialize form with initial date if provided
  useEffect(() => {
    if (initialDate && mode === 'create') {
      const startDateTime = new Date(initialDate)
      const endDateTime = new Date(initialDate)
      endDateTime.setHours(startDateTime.getHours() + 1)

      setFormData(prev => ({
        ...prev,
        start_time: startDateTime.toISOString().slice(0, 16),
        end_time: endDateTime.toISOString().slice(0, 16)
      }))
    }
  }, [initialDate, mode])

  // Fetch event data for edit mode
  useEffect(() => {
    if (mode === 'edit' && eventId) {
      fetchEvent(`/api/events/${eventId}`)
    }
  }, [mode, eventId, fetchEvent])

  // Populate form when event data is loaded
  useEffect(() => {
    if (eventData && mode === 'edit') {
      setFormData({
        name: eventData.title,
        description: eventData.description || '',
        event_type: eventData.event_type,
        start_time: new Date(eventData.start_time).toISOString().slice(0, 16),
        end_time: new Date(eventData.end_time).toISOString().slice(0, 16),
        venue_id: eventData.venue_id || '',
        created_by_user_id: eventData.created_by_user_id,
        is_recurring: eventData.is_recurring,
        recurrence_rule: eventData.recurrence_rule || ''
      })

      if (eventData.venues) {
        setVenueSearch(eventData.venues.name)
      }
    }
  }, [eventData, mode])

  // Fetch venues
  useEffect(() => {
    fetchVenues('/api/venues?limit=100')
  }, [fetchVenues])

  // Filter venues based on search
  const filteredVenues = venuesData?.venues?.filter(venue =>
    venue.name.toLowerCase().includes(venueSearch.toLowerCase()) ||
    venue.city?.toLowerCase().includes(venueSearch.toLowerCase()) ||
    venue.address?.toLowerCase().includes(venueSearch.toLowerCase())
  ) || []

  // Validation
  const validateForm = (): boolean => {
    const errors: Partial<Record<keyof EventFormData, string>> = {}

    // Required fields
    if (!formData.name.trim()) {
      errors.name = 'Event name is required'
    }
    if (!formData.event_type) {
      errors.event_type = 'Event type is required'
    }
    if (!formData.start_time) {
      errors.start_time = 'Start time is required'
    }
    if (!formData.end_time) {
      errors.end_time = 'End time is required'
    }

    // Time validation
    if (formData.start_time && formData.end_time) {
      const startDate = new Date(formData.start_time)
      const endDate = new Date(formData.end_time)

      if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
        errors.start_time = 'Invalid date format'
      } else {
        if (endDate <= startDate) {
          errors.end_time = 'End time must be after start time'
        }
        if (startDate < new Date() && mode === 'create') {
          errors.start_time = 'Start time cannot be in the past'
        }
      }
    }

    // Recurring event validation
    if (formData.is_recurring && !formData.recurrence_rule.trim()) {
      errors.recurrence_rule = 'Recurrence rule is required for recurring events'
    }

    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    try {
      const eventPayload = {
        name: formData.name.trim(),
        description: formData.description.trim(),
        event_type: formData.event_type,
        start_time: new Date(formData.start_time).toISOString(),
        end_time: new Date(formData.end_time).toISOString(),
        venue_id: formData.venue_id || undefined,
        created_by_user_id: formData.created_by_user_id,
        is_recurring: formData.is_recurring,
        recurrence_rule: formData.is_recurring ? formData.recurrence_rule : undefined
      }

      let result: Event
      if (mode === 'create') {
        result = await submitEvent('/api/events', {
          method: 'POST',
          body: eventPayload
        })
        setSuccessMessage('Event created successfully!')
      } else {
        result = await submitEvent(`/api/events/${eventId}`, {
          method: 'PUT',
          body: eventPayload
        })
        setSuccessMessage('Event updated successfully!')
      }

      if (onSuccess) {
        onSuccess(result)
      }

      // Reset form if creating
      if (mode === 'create') {
        setFormData({
          name: '',
          description: '',
          event_type: 'practice',
          start_time: '',
          end_time: '',
          venue_id: '',
          created_by_user_id: undefined,
          is_recurring: false,
          recurrence_rule: ''
        })
        setVenueSearch('')
      }

      // Clear success message after 3 seconds
      setTimeout(() => setSuccessMessage(''), 3000)

    } catch (error) {
      console.error('Form submission error:', error)
    }
  }

  // Handle venue selection
  const handleVenueSelect = (venue: Venue) => {
    setFormData(prev => ({ ...prev, venue_id: venue.id }))
    setVenueSearch(venue.name)
    setShowVenueDropdown(false)
  }

  // Get event type icon and color
  const getEventTypeIcon = (type: string) => {
    switch (type) {
      case 'game':
        return Users
      case 'practice':
        return Settings
      case 'tournament':
        return Trophy
      default:
        return Calendar
    }
  }

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'game':
        return 'bg-blue-600 hover:bg-blue-700'
      case 'practice':
        return 'bg-green-600 hover:bg-green-700'
      case 'tournament':
        return 'bg-purple-600 hover:bg-purple-700'
      default:
        return 'bg-gray-600 hover:bg-gray-700'
    }
  }

  const EventTypeIcon = getEventTypeIcon(formData.event_type)

  const formContent = (
    <motion.form
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      onSubmit={handleSubmit}
      className="space-y-6"
    >
      {/* Success Message */}
      {successMessage && (
        <motion.div variants={itemVariants}>
          <Alert className="border-green-200 bg-green-50">
            <Check className="h-4 w-4 text-green-600" />
            <AlertDescription className="text-green-800">
              {successMessage}
            </AlertDescription>
          </Alert>
        </motion.div>
      )}

      {/* Error Message */}
      {submitError && (
        <motion.div variants={itemVariants}>
          <Alert className="border-red-200 bg-red-50">
            <AlertTriangle className="h-4 w-4 text-red-600" />
            <AlertDescription className="text-red-800">
              {submitError}
            </AlertDescription>
          </Alert>
        </motion.div>
      )}

      {/* Basic Information */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Calendar className="h-5 w-5 mr-2 text-blue-600" />
              Event Information
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Event Name *
                </label>
                <Input
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  placeholder="Enter event name"
                  className={formErrors.name ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.name && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.name}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Event Type *
                </label>
                <select
                  value={formData.event_type}
                  onChange={(e) => setFormData(prev => ({
                    ...prev,
                    event_type: e.target.value as EventFormData['event_type']
                  }))}
                  className={`w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                    formErrors.event_type ? 'border-red-500' : 'border-gray-300'
                  }`}
                >
                  <option value="practice">Practice</option>
                  <option value="game">Game</option>
                  <option value="tournament">Tournament</option>
                </select>
                {formErrors.event_type && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.event_type}
                  </p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-medium text-gray-700">
                Description
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                rows={3}
                placeholder="Enter event description (optional)"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Schedule */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Clock className="h-5 w-5 mr-2 text-green-600" />
              Schedule
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Start Time *
                </label>
                <Input
                  type="datetime-local"
                  value={formData.start_time}
                  onChange={(e) => setFormData(prev => ({ ...prev, start_time: e.target.value }))}
                  className={formErrors.start_time ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.start_time && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.start_time}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  End Time *
                </label>
                <Input
                  type="datetime-local"
                  value={formData.end_time}
                  onChange={(e) => setFormData(prev => ({ ...prev, end_time: e.target.value }))}
                  className={formErrors.end_time ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.end_time && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.end_time}
                  </p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Venue Selection */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <MapPin className="h-5 w-5 mr-2 text-orange-600" />
              Venue
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <label className="block text-sm font-medium text-gray-700">
                Search and Select Venue
              </label>
              <div className="relative">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    value={venueSearch}
                    onChange={(e) => {
                      setVenueSearch(e.target.value)
                      setShowVenueDropdown(true)
                      if (!e.target.value) {
                        setFormData(prev => ({ ...prev, venue_id: '' }))
                      }
                    }}
                    onFocus={() => setShowVenueDropdown(true)}
                    placeholder="Search venues by name, city, or address..."
                    className="pl-10"
                  />
                  {formData.venue_id && (
                    <button
                      type="button"
                      onClick={() => {
                        setFormData(prev => ({ ...prev, venue_id: '' }))
                        setVenueSearch('')
                        setShowVenueDropdown(true)
                      }}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2"
                    >
                      <X className="h-4 w-4 text-gray-400 hover:text-gray-600" />
                    </button>
                  )}
                </div>

                {/* Venue Dropdown */}
                {showVenueDropdown && venueSearch && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-md shadow-lg max-h-60 overflow-y-auto">
                    {venuesLoading ? (
                      <div className="p-3 text-center text-gray-500">
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mx-auto"></div>
                      </div>
                    ) : filteredVenues.length > 0 ? (
                      filteredVenues.map(venue => (
                        <div
                          key={venue.id}
                          onClick={() => handleVenueSelect(venue)}
                          className="p-3 hover:bg-gray-50 cursor-pointer border-b last:border-b-0"
                        >
                          <div className="font-medium text-gray-900">{venue.name}</div>
                          {venue.address && (
                            <div className="text-sm text-gray-500">
                              {venue.address}
                              {venue.city && `, ${venue.city}`}
                              {venue.state && `, ${venue.state}`}
                            </div>
                          )}
                          {venue.capacity && (
                            <div className="text-sm text-gray-500">
                              Capacity: {venue.capacity}
                            </div>
                          )}
                        </div>
                      ))
                    ) : (
                      <div className="p-3 text-center text-gray-500">
                        No venues found matching "{venueSearch}"
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Selected venue display */}
              {formData.venue_id && (
                <div className="p-3 bg-green-50 border border-green-200 rounded-md">
                  <div className="flex items-center text-green-800">
                    <Check className="h-4 w-4 mr-2" />
                    <span className="font-medium">Venue selected: {venueSearch}</span>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Recurring Event */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Repeat className="h-5 w-5 mr-2 text-purple-600" />
              Recurrence
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-4">
              <label className="flex items-center space-x-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.is_recurring}
                  onChange={(e) => setFormData(prev => ({
                    ...prev,
                    is_recurring: e.target.checked,
                    recurrence_rule: e.target.checked ? prev.recurrence_rule : ''
                  }))}
                  className="rounded border-gray-300 focus:ring-blue-500"
                />
                <span className="text-sm font-medium text-gray-700">
                  This is a recurring event
                </span>
              </label>

              {formData.is_recurring && (
                <div className="space-y-2 pl-6">
                  <label className="block text-sm font-medium text-gray-700">
                    Recurrence Pattern *
                  </label>
                  <select
                    value={formData.recurrence_rule}
                    onChange={(e) => setFormData(prev => ({ ...prev, recurrence_rule: e.target.value }))}
                    className={`w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                      formErrors.recurrence_rule ? 'border-red-500' : 'border-gray-300'
                    }`}
                  >
                    <option value="">Select recurrence pattern...</option>
                    <option value="DAILY">Daily</option>
                    <option value="WEEKLY">Weekly</option>
                    <option value="BIWEEKLY">Every 2 weeks</option>
                    <option value="MONTHLY">Monthly</option>
                  </select>
                  {formErrors.recurrence_rule && (
                    <p className="text-sm text-red-600 flex items-center">
                      <AlertTriangle className="h-4 w-4 mr-1" />
                      {formErrors.recurrence_rule}
                    </p>
                  )}
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Form Actions */}
      <motion.div variants={itemVariants} className="flex justify-end space-x-4 pt-6">
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={submitting}
          >
            Cancel
          </Button>
        )}
        <Button
          type="submit"
          disabled={submitting || eventLoading}
          className={`${getEventTypeColor(formData.event_type)} text-white flex items-center`}
        >
          {submitting ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
              {mode === 'create' ? 'Creating...' : 'Updating...'}
            </>
          ) : (
            <>
              <EventTypeIcon className="h-4 w-4 mr-2" />
              {mode === 'create' ? 'Create Event' : 'Update Event'}
            </>
          )}
        </Button>
      </motion.div>
    </motion.form>
  )

  // Handle click outside to close venue dropdown
  useEffect(() => {
    const handleClickOutside = () => setShowVenueDropdown(false)
    if (showVenueDropdown) {
      document.addEventListener('click', handleClickOutside)
      return () => document.removeEventListener('click', handleClickOutside)
    }
  }, [showVenueDropdown])

  if (isModal) {
    return (
      <Dialog open={true} onOpenChange={onCancel}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <div className="flex items-center justify-center mb-4">
              <div className={`w-12 h-12 ${getEventTypeColor(formData.event_type)} rounded-full flex items-center justify-center shadow-lg`}>
                <EventTypeIcon className="w-6 h-6 text-white" />
              </div>
            </div>
            <DialogTitle className="text-center text-2xl font-bold">
              {mode === 'create' ? 'Create New Event' : 'Edit Event'}
            </DialogTitle>
            <DialogDescription className="text-center">
              {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
            </DialogDescription>
          </DialogHeader>

          {eventLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
              <span className="ml-2 text-gray-600">Loading event...</span>
            </div>
          ) : (
            formContent
          )}
        </DialogContent>
      </Dialog>
    )
  }

  // Standalone page mode
  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="mb-6">
        <div className="flex items-center space-x-4 mb-4">
          <div className={`w-12 h-12 ${getEventTypeColor(formData.event_type)} rounded-full flex items-center justify-center shadow-lg`}>
            <EventTypeIcon className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">
              {mode === 'create' ? 'Create New Event' : 'Edit Event'}
            </h1>
            <p className="text-gray-600">
              {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
            </p>
          </div>
        </div>
      </div>

      {eventLoading ? (
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          <span className="ml-2 text-gray-600">Loading event...</span>
        </div>
      ) : (
        formContent
      )}
    </div>
  )
}

import { useEffect, useState, useCallback } from 'react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import { Checkbox } from './ui/checkbox'
import { Search, Users, Shield, AlertTriangle, Check, X } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

interface Team {
  id: number
  name: string
  organization: string
  division?: string
  age_group?: string
  skill_level?: string
  created_at: string
}

interface TeamSelectorForEventProps {
  selectedTeamIds: number[]
  onTeamsChange: (teamIds: number[]) => void
  disabled?: boolean
  className?: string
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05,
      delayChildren: 0.1
    }
  }
} as const

const itemVariants = {
  hidden: { y: 10, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      type: "spring" as const,
      stiffness: 300,
      damping: 20
    }
  }
} as const

export default function TeamSelectorForEvent({
  selectedTeamIds,
  onTeamsChange,
  disabled = false,
  className = ''
}: TeamSelectorForEventProps) {
  const [teams, setTeams] = useState<Team[]>([])
  const [filteredTeams, setFilteredTeams] = useState<Team[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState('')

  useEffect(() => {
    fetchTeams()
  }, [])

  useEffect(() => {
    const filtered = teams.filter(team =>
      team.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      team.organization.toLowerCase().includes(searchTerm.toLowerCase()) ||
      team.division?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      team.age_group?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    setFilteredTeams(filtered)
  }, [teams, searchTerm])

  const fetchTeams = async () => {
    try {
      setLoading(true)
      setError(null)
      const response = await fetch('/api/teams')
      if (!response.ok) {
        throw new Error('Failed to fetch teams')
      }
      const data = await response.json()
      const teamsArray = data.teams || data
      setTeams(teamsArray)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load teams'
      setError(errorMessage)
      console.error('Fetch teams error:', err)
    } finally {
      setLoading(false)
    }
  }

  const handleTeamToggle = useCallback((teamId: number) => {
    if (disabled) return

    const newSelectedIds = selectedTeamIds.includes(teamId)
      ? selectedTeamIds.filter(id => id !== teamId)
      : [...selectedTeamIds, teamId]

    onTeamsChange(newSelectedIds)
  }, [selectedTeamIds, onTeamsChange, disabled])

  const handleSelectAll = useCallback(() => {
    if (disabled) return

    if (selectedTeamIds.length === filteredTeams.length) {
      onTeamsChange([])
    } else {
      onTeamsChange(filteredTeams.map(team => team.id))
    }
  }, [selectedTeamIds, filteredTeams, onTeamsChange, disabled])

  const handleClearSelection = useCallback(() => {
    if (disabled) return
    onTeamsChange([])
  }, [onTeamsChange, disabled])

  if (loading) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="glass-card p-6">
          <div className="flex items-center justify-center py-8">
            <motion.div
              animate={{ rotate: 360 }}
              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
              className="w-8 h-8 border-2 border-gray-200 border-t-blue-600 rounded-full"
            />
            <span className="ml-3 text-gray-600">Loading teams...</span>
          </div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="glass-card p-6 border-red-500/20">
          <div className="flex items-center space-x-2 text-red-600 mb-4">
            <AlertTriangle className="h-5 w-5" />
            <span className="font-medium">Error loading teams</span>
          </div>
          <p className="text-red-600 mb-4">{error}</p>
          <Button
            onClick={fetchTeams}
            variant="outline"
            size="sm"
            className="border-red-300 text-red-600 hover:bg-red-50"
          >
            Try Again
          </Button>
        </div>
      </div>
    )
  }

  return (
    <div className={`space-y-4 ${className}`}>
      <motion.div
        initial="hidden"
        animate="visible"
        variants={containerVariants}
        className="glass-card glass-card-hover p-6"
      >
        {/* Header */}
        <motion.div variants={itemVariants} className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-3">
            <div className="p-2 rounded-lg bg-blue-100 dark:bg-blue-900/20">
              <Users className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                Select Teams
              </h3>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {selectedTeamIds.length} of {filteredTeams.length} teams selected
              </p>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center space-x-2">
            <Button
              onClick={handleSelectAll}
              disabled={disabled || filteredTeams.length === 0}
              variant="outline"
              size="sm"
              className="text-xs"
            >
              {selectedTeamIds.length === filteredTeams.length ? (
                <>
                  <X className="h-3 w-3 mr-1" />
                  Deselect All
                </>
              ) : (
                <>
                  <Check className="h-3 w-3 mr-1" />
                  Select All
                </>
              )}
            </Button>
            {selectedTeamIds.length > 0 && (
              <Button
                onClick={handleClearSelection}
                disabled={disabled}
                variant="outline"
                size="sm"
                className="text-xs text-red-600 border-red-300 hover:bg-red-50"
              >
                <X className="h-3 w-3 mr-1" />
                Clear
              </Button>
            )}
          </div>
        </motion.div>

        {/* Search */}
        <motion.div variants={itemVariants} className="mb-6">
          <div className="relative">
            <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Search teams by name, organization, division..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              disabled={disabled}
              className="pl-10 bg-white/50 dark:bg-gray-800/50 backdrop-blur-sm border-gray-200/50 dark:border-gray-700/50"
            />
          </div>
        </motion.div>

        {/* Teams List */}
        <div className="space-y-2 max-h-80 overflow-y-auto">
          <AnimatePresence>
            {filteredTeams.map((team, index) => (
              <motion.div
                key={team.id}
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                exit={{ opacity: 0, scale: 0.95 }}
                custom={index}
                className={`group relative p-4 rounded-lg border transition-all duration-200 ${
                  selectedTeamIds.includes(team.id)
                    ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-700 shadow-sm'
                    : 'bg-white/50 dark:bg-gray-800/50 border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800/70'
                } ${
                  disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'
                }`}
                onClick={() => handleTeamToggle(team.id)}
              >
                <div className="flex items-center space-x-4">
                  {/* Checkbox */}
                  <Checkbox
                    checked={selectedTeamIds.includes(team.id)}
                    disabled={disabled}
                    onChange={() => handleTeamToggle(team.id)}
                  />

                  {/* Team Icon */}
                  <div className={`p-2 rounded-lg transition-colors ${
                    selectedTeamIds.includes(team.id)
                      ? 'bg-blue-100 dark:bg-blue-800/30'
                      : 'bg-gray-100 dark:bg-gray-700 group-hover:bg-gray-200 dark:group-hover:bg-gray-600'
                  }`}>
                    <Shield className={`h-4 w-4 ${
                      selectedTeamIds.includes(team.id)
                        ? 'text-blue-600'
                        : 'text-gray-600 dark:text-gray-400'
                    }`} />
                  </div>

                  {/* Team Details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between">
                      <h4 className="font-medium text-gray-900 dark:text-white truncate">
                        {team.name}
                      </h4>
                      {selectedTeamIds.includes(team.id) && (
                        <motion.div
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          className="text-blue-600"
                        >
                          <Check className="h-4 w-4" />
                        </motion.div>
                      )}
                    </div>
                    <p className="text-sm text-gray-600 dark:text-gray-400 truncate">
                      {team.organization}
                    </p>
                    {(team.division || team.age_group) && (
                      <div className="flex items-center space-x-2 mt-1">
                        {team.division && (
                          <span className="text-xs px-2 py-1 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded">
                            {team.division}
                          </span>
                        )}
                        {team.age_group && (
                          <span className="text-xs px-2 py-1 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded">
                            {team.age_group}
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>

        {/* Empty State */}
        {filteredTeams.length === 0 && !loading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center py-8"
          >
            <Users className="h-12 w-12 mx-auto text-gray-300 mb-4" />
            <h3 className="text-lg font-medium text-gray-700 dark:text-gray-300 mb-2">
              {searchTerm ? 'No teams found' : 'No teams available'}
            </h3>
            <p className="text-gray-500">
              {searchTerm
                ? 'Try adjusting your search criteria'
                : 'Teams will appear here when they are added to the system'
              }
            </p>
          </motion.div>
        )}
      </motion.div>

      {/* Selected Teams Summary */}
      <AnimatePresence>
        {selectedTeamIds.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="glass-card p-4"
          >
            <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Selected Teams ({selectedTeamIds.length})
            </h4>
            <div className="flex flex-wrap gap-2">
              {selectedTeamIds.map(teamId => {
                const team = teams.find(t => t.id === teamId)
                if (!team) return null

                return (
                  <motion.span
                    key={teamId}
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    exit={{ scale: 0 }}
                    className="inline-flex items-center px-3 py-1 rounded-full text-sm bg-blue-100 dark:bg-blue-900/20 text-blue-800 dark:text-blue-300"
                  >
                    {team.name}
                    {!disabled && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          handleTeamToggle(teamId)
                        }}
                        className="ml-2 text-blue-600 hover:text-blue-800 transition-colors"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    )}
                  </motion.span>
                )
              })}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

